describe('Search Results - Highlighted Search Terms', () => {
  const searchUrl = 'https://example.com/search';
  const testSearchTerm = 'automation testing';
  const alternativeSearchTerm = 'cypress framework';

  beforeEach(() => {
    cy.visit(searchUrl);
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should highlight search terms in result snippets with visual emphasis', () => {
    cy.get('[data-testid="search-input"]').type(testSearchTerm);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="result-snippet"]').each(($snippet) => {
      const snippetText = $snippet.text().toLowerCase();
      expect(snippetText).to.include(testSearchTerm.toLowerCase());

      cy.wrap($snippet).within(() => {
        cy.get('[data-testid="highlighted-term"]').should('exist');
        cy.get('[data-testid="highlighted-term"]').should('have.css', 'background-color');
        cy.get('[data-testid="highlighted-term"]').should('have.css', 'font-weight');
      });
    });
  });

  it('should highlight multiple occurrences of search terms in snippets', () => {
    cy.get('[data-testid="search-input"]').type(testSearchTerm);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');

    cy.get('[data-testid="result-snippet"]').first().within(() => {
      const highlightedElements = cy.get('[data-testid="highlighted-term"]');
      highlightedElements.should('have.length.greaterThan', 0);

      highlightedElements.each(($element) => {
        const highlightedText = $element.text().toLowerCase();
        expect(testSearchTerm.toLowerCase()).to.include(highlightedText);
        cy.wrap($element).should('have.css', 'background-color').and('not.equal', 'rgba(0, 0, 0, 0)');
      });
    });
  });

  it('should handle special characters in search terms and highlight correctly', () => {
    const specialSearchTerm = 'test-case';
    cy.get('[data-testid="search-input"]').type(specialSearchTerm);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-snippet"]').should('have.length.greaterThan', 0);

    cy.get('[data-testid="result-snippet"]').first().within(() => {
      cy.get('[data-testid="highlighted-term"]').should('exist');
      cy.get('[data-testid="highlighted-term"]').first().should('contain.text', 'test');
    });
  });

  it('should not highlight terms when search returns no results', () => {
    const nonexistentTerm = 'xyznonexistentterm123';
    cy.get('[data-testid="search-input"]').type(nonexistentTerm);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="result-snippet"]').should('not.exist');
    cy.get('[data-testid="highlighted-term"]').should('not.exist');
  });

  it('should maintain highlight styling across different result types', () => {
    cy.get('[data-testid="search-input"]').type(alternativeSearchTerm);
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('be.visible');

    cy.get('[data-testid="result-item"]').each(($result) => {
      cy.wrap($result).within(() => {
        const resultType = cy.wrap($result).invoke('attr', 'data-result-type');
        cy.get('[data-testid="result-snippet"]').within(() => {
          cy.get('[data-testid="highlighted-term"]').should('exist');
          cy.get('[data-testid="highlighted-term"]').should('have.css', 'color');
        });
      });
    });
  });

  it('should clear highlights when search is cleared', () => {
    cy.get('[data-testid="search-input"]').type(testSearchTerm);
    cy.get('[data-testid="search-button"]').click();
    cy.get('[data-testid="highlighted-term"]').should('exist');

    cy.get('[data-testid="search-input"]').clear();
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="search-results"]').should('not.exist');
    cy.get('[data-testid="highlighted-term"]').should('not.exist');
  });
});
